  synchronized void report(boolean ok,String failure){if(finished)return;finished=true;JSONObject report=J.obj("kind","result","status",ok?"passed":"failed","checkCount",checks.length(),"checks",checks,"actualAndroidExecution",true,"actualNativeExecution",true,"actualMihomoExecution",true,"coreVersion",coreVersion,"coreSha256",coreSha256,"coreAbi",android.os.Build.SUPPORTED_ABIS[0],"actualKeystoreEncryption",true,"actualRouteApplication",false,"failure",failure,"scope","Official app-local Mihomo provider parsing and Android Keystore encrypted snapshots. No public subscription, actual proxy connection or real account is used; live route IPC/application is verified separately.");try{J.write(new File(getFilesDir(),"network-source-results.json"),report.toString(2));}catch(Exception error){android.util.Log.e("PocketNetworkSources","Could not save report",error);}JSONObject summary=J.parse(report.toString());summary.remove("checks");android.util.Log.i("PocketNetworkSources",summary.toString());}
